export const sample={brand:'NOMA',product:'便携咖啡机',description:'一款注重设计与品质的便携咖啡机，让日常咖啡仪式不受地点限制。',brandDescription:'为自在探索生活的人，打造经过细心设计的日常用品。',keywords:['简约','都市','温暖','独立'],sellingPoints:'轻巧便携\n随时随地享用好咖啡\n精致工业设计\n简单易用',goal:'新品上市',objective:'通过社媒和电商，为新款便携咖啡机做上市推广。',audience:'25–35 岁的都市职场人与旅行爱好者',references:['https://fellowproducts.com','https://www.aesop.com','https://www.patagonia.com'],referenceNotes:'参考 Fellow 对产品设计的重视、Aesop 克制的高级感，以及 Patagonia 自由探索的气质。',images:[]};
export const referenceAnalysisProvider={async analyze(references,notes){return {mode:'mock',references,notes,summary:references.length?`已保存 ${references.length} 个参考链接。以下解读为演示假设，并非实时网页分析。`:'暂未添加参考，将根据产品与品牌需求探索方向。'}}};
export const llmProvider={async summarize(p){const r=await referenceAnalysisProvider.analyze(p.references,p.referenceNotes);return {product:`${p.brand} ${p.product}. ${p.description||''}`, 'core message':p.brand==='NOMA'?"好咖啡，不该受地点限制。":`${p.product}，为${p.audience||'你的日常生活'}而设计。`,audience:p.audience||'受众尚待确认，可在创作中逐步明确。',opportunity:p.brand==='NOMA'?'不止讲功能，让便携咖啡机承载属于自己的日常仪式。':`把${p.sellingPoints.split('\n')[0]||'产品卖点'}与受众熟悉的生活场景联系起来。`,goal:p.objective||p.goal,references:r.summary}}};
export const analyzeBrief=p=>llmProvider.summarize(p);
export async function createDirections(p){const coffee=/coffee|咖啡/i.test(p.product);const brandMood=[...p.keywords,...(p.customKeywords||'').split(',').filter(Boolean)];return [{id:'a',name:coffee?'随行咖啡时刻':'重新发现日常',concept:coffee?'在日常生活的不同角落，留出一个属于自己的咖啡时刻。让熟悉的仪式，陪你去新的地方。':`将${p.product}带入新鲜的日常场景，让${p.sellingPoints.split('\n')[0]||'核心价值'}被看见。`,visualDirection:'自然光 / 城市肌理 / 温暖的纪实摄影',keyMessage:coffee?'走到哪里，都有自己的咖啡时刻。':`${p.product}，融入你的每一天。`,mood:['独立','温暖','松弛'],palette:['#dfccb0','#777c60','#484c42','#b38656'],image:'/assets/a.png',references:p.references},{id:'b',name:'为日常仪式而设计',concept:`让${p.product}的设计自己说话。放慢脚步，靠近一点，看见用心的细节。`,visualDirection:'雕塑感静物 / 精准光影 / 安静简约的构图',keyMessage:coffee?'好设计，让清晨更美好。':'用心设计，日常也有好心情。',mood:['高级','简约',brandMood.includes('自然')?'自然':'考究'],palette:['#dedbd0','#b6b1a5','#54554e','#282b26'],image:'/assets/b.png',references:p.references},{id:'c',name:'跳出日常',concept:`让 ${p.brand} 成为跳出日常的邀请。用意外的色彩、有趣的比例，打开生活的更多可能。`,visualDirection:'大胆撞色 / 图形化构图 / 明快的户外光线',keyMessage:coffee?'好咖啡，不设固定地点。':'带着日常，去点新地方。',mood:['大胆','年轻','探索'],palette:['#4168b4','#ed934c','#e2d9c7','#223e70'],image:'/assets/c.png',references:p.references}]}
export async function refineDirection(d,feedback){const premium=/premium|minimal|高级|简约|direction 02|like b|为日常仪式而设计/i.test(feedback),warm=/warm|温暖|暖色/i.test(feedback);return {...d,feedback,visualDirection:premium?'雕塑感棚拍光线 / 精致中性色 / 充足留白':warm?'金色自然光 / 温暖材质感 / 亲近的构图':d.visualDirection,concept:premium?`${d.concept} 以克制、精致的视觉风格呈现。`:warm?`${d.concept} 强调温暖感与个人情感。`:`${d.concept} 调整要求：${feedback}`,mood:premium?['高级','考究','独立']:warm?['温暖','亲近','松弛']:d.mood,image:premium?'/assets/b.png':warm?'/assets/a.png':d.image}}
export const imageGenerationProvider={async compose(p,d,type){
 const premium=d.id==='b'||/studio|sculptural|棚拍|雕塑/i.test(d.visualDirection);
 const image=p.images?.[0]||(type==='social'?'/assets/a.png':type==='product'?'/assets/material-detail.png':d.image);
 return {image,text:type==='product'?'每处细节，都有考究。':d.keyMessage,filter:premium?'saturate(.65)':'none',scale:1,position:'center',feedback:'',change:'静态示例素材 · 本地构图，并非实时图像生成。'};
}};
export async function generateCampaign(p){const d=p.creativeDirections.find(x=>x.id===p.selectedDirection);return Promise.all([{id:'hero',type:'主视觉',format:'推广主视觉 · 4:3'},{id:'product',type:'产品图',format:'产品细节 · 4:3'},{id:'social',type:'社媒配图',format:'社媒帖子 · 1:1'}].map(async a=>({...a,expression:a.id==='hero'?'雕塑感产品形象 · 建立推广视觉识别':a.id==='product'?'材质与结构 · 看见设计细节':'真实晨间场景 · 自己的咖啡仪式',context:{direction:d.id,directionName:d.name,keyMessage:d.keyMessage,visualDirection:d.visualDirection,concept:d.concept},versions:[await imageGenerationProvider.compose(p,d,a.id)]})))}
export async function reviseAsset(v,feedback){const n={...v,feedback};let changes=[];if(/prominent|larger|bigger|突出|放大/i.test(feedback)){n.scale=Math.min((v.scale||1)+.18,1.9);changes.push('已放大产品构图')}if(/warm|温暖|暖色/i.test(feedback)){n.filter='sepia(.25) saturate(1.15)';changes.push('已调整为温暖色调')}if(/reduce.*text|less text|remove.*text|减少|文字/i.test(feedback)){n.text='';changes.push('已移除画面文字')}if(/background|背景/i.test(feedback)){n.background=/blue|蓝/i.test(feedback)?'#b8d1f0':/pink|粉/i.test(feedback)?'#eac9c3':'#ddc9ab';changes.push('已调整背景色调（演示混色）')}if(/instagram|square|正方形|社媒/i.test(feedback)){n.scale=1.2;n.position='center';changes.push('已采用适合社媒的居中构图')}n.change=changes.length?changes.join(' · '):'已保存反馈。此类修改需要接入图像模型，当前画面暂未改变。';return n}
